H.background();
// Slope from a graph: pick two points (x1,y1) and (x2,y2) on a line.
// slope m = rise / run = (y2 - y1) / (x2 - x1). Show the rise/run triangle.
const x1 = P.x1, y1 = P.y1, x2 = P.x2, y2 = P.y2;
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -8, yMax: 8 });
v.grid(); v.axes();
const run = x2 - x1, rise = y2 - y1;
const denomOk = Math.abs(run) > 1e-9;
const m = denomOk ? rise / run : NaN;
// the full line through the two points
if (denomOk) v.fn(x => y1 + m * (x - x1), { color: H.colors.accent, width: 3 });
else v.line(x1, -8, x1, 8, { color: H.colors.accent, width: 3 }); // vertical: undefined slope
// rise/run right triangle: horizontal leg then vertical leg
v.line(x1, y1, x2, y1, { color: H.colors.good, width: 3 });       // run
v.line(x2, y1, x2, y2, { color: H.colors.violet, width: 3 });     // rise
v.text("run = " + run.toFixed(1), (x1 + x2) / 2, y1 - 0.6, { color: H.colors.good, size: 12, align: "center" });
v.text("rise = " + rise.toFixed(1), x2 + 0.4, (y1 + y2) / 2, { color: H.colors.violet, size: 12 });
// the two chosen points
v.dot(x1, y1, { r: 6, fill: H.colors.accent2 });
v.dot(x2, y2, { r: 6, fill: H.colors.accent2 });
v.text("(" + x1.toFixed(1) + ", " + y1.toFixed(1) + ")", x1, y1 + 0.8, { color: H.colors.sub, size: 11, align: "center" });
v.text("(" + x2.toFixed(1) + ", " + y2.toFixed(1) + ")", x2, y2 + 0.8, { color: H.colors.sub, size: 11, align: "center" });
// animated dot riding the line between the two points (loops back and forth)
